def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3]
    for r,c in pts:
        for dc in range(-2,3):
            if 0<=r-2<h and 0<=c+dc<w: out[r-2][c+dc]=5
        for dr in (-1,0,1):
            rr=r+dr
            for cc in (c-2,c+2):
                if 0<=rr<h and 0<=cc<w: out[rr][cc]=2
        if 0<=r-1<h and 0<=c<w: out[r-1][c]=5
        rr=r+2
        if 0<=rr<h:
            out[rr]=[2]*w
            for cc in range(c-2,c+3):
                if 0<=cc<w: out[rr][cc]=8
    return out

